INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(41363, 0, 0, 0, 0, 0, 0, 0, 0, 'Intriguing. These samples radiate a magic not unfamiliar to me, on first glance I\'d even say they emanate druidic magic. Ofcourse, I shouldn\'t jump to conclusions. Further research within the Cenarion Circle will be needed. Surely their venerable druids can solve the origin of their volatile growth.$B$B$N, you have my appreciation. Please, take one of these as compensation for your troubles.', 0),
(41367, 0, 0, 0, 0, 0, 0, 0, 0, 'The darkness of the nightmare loomed over my on thoughts, breaking free emotions that I would usually keep in check. In a way, I regret it has come to this.$B$B<Nalpak sets Zandara\'s head on the ground.>$B$BA job well done, is a job well rewarded. You have my thanks $N.', 0),
(60124, 0, 0, 0, 0, 0, 0, 0, 0, 'The news came just before you arrived. We\'re truly in your debt.$B$BHere, a reward fitting for a hero such as yourself.', 0),
(60125, 0, 0, 0, 0, 0, 0, 0, 0, 'You did find them! I will send these to Moonglade immediately.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(41363, 0, 0, 'Be careful. Not only is this den of nightmares highly dangerous, but also your journey through Horde territory.', 0),
(41367, 0, 0, 'One nightmare after the other.', 0),
(60124, 4, 18, 'Only you and your friends can save Naralex, you are our only hope.', 0),
(60125, 4, 6, 'Did you collect the flowers? They might reveal something about the Nightmare.', 0);
